import {
  index,
  integer,
  primaryKey,
  real,
  sqliteTable,
  text,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";

import { user } from "./auth-schema";

// Better Auth tables (user, session, account, verification) — generated by
// `@better-auth/cli generate`; do not edit by hand.
export * from "./auth-schema";

/**
 * Provider credentials, **encrypted at rest** (envelope encryption; see
 * `docs/decisions/0001-key-vault.md`). Only ciphertext is stored — never the
 * plaintext key. A per-record DEK (AES-256-GCM) encrypts the secret; the DEK is
 * wrapped with the deployment KEK (AES-256-KW).
 */
export const providerCredentials = sqliteTable(
  "provider_credentials",
  {
    id: text("id").primaryKey(),
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    provider: text("provider").notNull(), // "gemini" | "groq" (POC)
    label: text("label").notNull().default(""),
    keyVersion: integer("key_version").notNull(),
    wrappedDek: text("wrapped_dek").notNull(), // base64 AES-KW(DEK)
    iv: text("iv").notNull(), // base64 96-bit IV
    ciphertext: text("ciphertext").notNull(), // base64 AES-GCM(secret)
    fingerprint: text("fingerprint").notNull(), // SHA-256 of the plaintext
    createdAt: text("created_at").notNull(),
    updatedAt: text("updated_at").notNull(),
  },
  (table) => [
    index("provider_credentials_ownerId_idx").on(table.ownerId),
    uniqueIndex("provider_credentials_owner_provider_label_unq").on(
      table.ownerId,
      table.provider,
      table.label,
    ),
  ],
);

/**
 * Gateway API keys for programmatic access (KAN-28). Only a SHA-256 hash of the
 * token is stored; the token is shown once at creation.
 */
export const apiKeys = sqliteTable(
  "api_keys",
  {
    id: text("id").primaryKey(),
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    prefix: text("prefix").notNull(),
    hash: text("hash").notNull().unique(),
    createdAt: text("created_at").notNull(),
    lastUsedAt: text("last_used_at"),
    revokedAt: text("revoked_at"),
  },
  (table) => [index("api_keys_ownerId_idx").on(table.ownerId)],
);

/**
 * Static free-tier model catalog for the POC (seeded in D1; not live-probed).
 */
export const freeModels = sqliteTable(
  "free_models",
  {
    provider: text("provider").notNull(),
    modelId: text("model_id").notNull(),
    label: text("label").notNull(),
    context: integer("context"),
    free: integer("free", { mode: "boolean" }).notNull().default(true),
    sort: integer("sort").notNull().default(0),
    /** When the catalog sync last confirmed this row (ISO-8601). */
    lastCheckedAt: text("last_checked_at"),
    /** When the row's label/context/note last changed (ISO-8601). */
    updatedAt: text("updated_at"),
    /** Why the model is considered free, e.g. "free tier (rate-limited)". */
    note: text("note"),
  },
  (table) => [primaryKey({ columns: [table.provider, table.modelId] })],
);

/**
 * Probe cache: models a provider lists but that a probe rejected (the key
 * cannot use them, or they are not chat models). Without this, every nightly
 * run would re-probe the same rejects and starve the models behind them.
 */
export const catalogProbes = sqliteTable(
  "catalog_probes",
  {
    provider: text("provider").notNull(),
    modelId: text("model_id").notNull(),
    /** The probe status that caused the rejection. */
    status: text("status").notNull(),
    checkedAt: text("checked_at").notNull(),
  },
  (table) => [primaryKey({ columns: [table.provider, table.modelId] })],
);

/**
 * One row per catalog sync run (KAN-44). The nightly cron refreshes
 * `free_models` from each provider's live model list; this is the audit trail.
 * Also the raw material for the SLO dashboards in KAN-7.
 */
export const catalogRuns = sqliteTable("catalog_runs", {
  id: text("id").primaryKey(),
  startedAt: text("started_at").notNull(),
  finishedAt: text("finished_at"),
  /** "cron" | "manual". */
  trigger: text("trigger").notNull(),
  /** "running" | "ok" | "partial" | "skipped" | "failed". */
  status: text("status").notNull(),
  /** JSON array of per-provider outcomes. */
  providers: text("providers").notNull().default("[]"),
  error: text("error"),
});

/**
 * Chat conversations and messages (KAN-39). Owner-scoped; a conversation and
 * its messages cascade-delete with the user. Assistant messages persist the
 * provider/model and performance metadata (TTFT, tokens).
 */
export const conversations = sqliteTable(
  "conversations",
  {
    id: text("id").primaryKey(),
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text("title").notNull().default(""),
    model: text("model").notNull().default(""),
    provider: text("provider"),
    createdAt: text("created_at").notNull(),
    updatedAt: text("updated_at").notNull(),
  },
  (table) => [
    index("conversations_ownerId_updatedAt_idx").on(
      table.ownerId,
      table.updatedAt,
    ),
  ],
);

export const messages = sqliteTable(
  "messages",
  {
    id: text("id").primaryKey(),
    conversationId: text("conversation_id")
      .notNull()
      .references(() => conversations.id, { onDelete: "cascade" }),
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    role: text("role").notNull(),
    content: text("content").notNull(),
    model: text("model"),
    provider: text("provider"),
    promptTokens: integer("prompt_tokens"),
    completionTokens: integer("completion_tokens"),
    reasoningTokens: integer("reasoning_tokens"),
    ttftMs: integer("ttft_ms"),
    totalMs: integer("total_ms"),
    stopped: integer("stopped", { mode: "boolean" }).notNull().default(false),
    createdAt: text("created_at").notNull(),
  },
  (table) => [
    index("messages_conversationId_createdAt_idx").on(
      table.conversationId,
      table.createdAt,
    ),
  ],
);

/**
 * One row per user-triggered probe report (KAN-46). Owner-scoped; the run
 * probes every model the provider lists with the caller's credential.
 */
export const probeRuns = sqliteTable(
  "probe_runs",
  {
    id: text("id").primaryKey(),
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    credentialId: text("credential_id").references(
      () => providerCredentials.id,
      { onDelete: "set null" },
    ),
    provider: text("provider").notNull(),
    label: text("label"),
    /** queued | running | succeeded | failed */
    status: text("status").notNull(),
    /** manual (cron later) */
    trigger: text("trigger").notNull(),
    createdAt: text("created_at").notNull(),
    startedAt: text("started_at"),
    finishedAt: text("finished_at"),
    durationMs: integer("duration_ms"),
    progressDone: integer("progress_done").notNull().default(0),
    progressTotal: integer("progress_total").notNull().default(0),
    totalsJson: text("totals_json").notNull().default("{}"),
    error: text("error"),
  },
  (table) => [
    index("probe_runs_owner_created_idx").on(table.ownerId, table.createdAt),
  ],
);

/** Per-model outcome of a report, including failure evidence. */
export const probeRunModels = sqliteTable(
  "probe_run_models",
  {
    id: text("id").primaryKey(),
    runId: text("run_id")
      .notNull()
      .references(() => probeRuns.id, { onDelete: "cascade" }),
    /** Denormalized so availability/FK-safe queries stay owner-scoped. */
    ownerId: text("owner_id").notNull(),
    provider: text("provider").notNull(),
    modelId: text("model_id").notNull(),
    resolvedModel: text("resolved_model"),
    kind: text("kind").notNull(),
    attempted: integer("attempted", { mode: "boolean" }).notNull(),
    ok: integer("ok", { mode: "boolean" }).notNull(),
    status: integer("status"),
    statusText: text("status_text"),
    durationMs: integer("duration_ms"),
    ttftMs: integer("ttft_ms"),
    completionTokens: integer("completion_tokens"),
    reasoningTokens: integer("reasoning_tokens"),
    tps: real("tps"),
    thinking: integer("thinking", { mode: "boolean" }),
    content: text("content"),
    errorName: text("error_name"),
    errorMessage: text("error_message"),
    /** Response evidence only — request auth headers are never persisted. */
    body: text("body"),
    requestBody: text("request_body"),
    headersJson: text("headers_json"),
    quotaState: text("quota_state"),
    quotaLimitsJson: text("quota_limits_json"),
    quotaRetryAfterMs: integer("quota_retry_after_ms"),
    createdAt: text("created_at").notNull(),
  },
  (table) => [
    index("probe_run_models_run_idx").on(table.runId),
    index("probe_run_models_owner_model_idx").on(
      table.ownerId,
      table.provider,
      table.modelId,
      table.createdAt,
    ),
  ],
);

/**
 * Materialized per-user model availability (KAN-46), written when a report
 * finishes and read by the chat model picker. `last_ok_at` is the recency
 * anchor (TTL via `AVAILABILITY_TTL_DAYS`).
 */
export const modelAvailability = sqliteTable(
  "model_availability",
  {
    ownerId: text("owner_id").notNull(),
    provider: text("provider").notNull(),
    modelId: text("model_id").notNull(),
    resolvedModel: text("resolved_model"),
    available: integer("available", { mode: "boolean" }).notNull(),
    lastStatus: integer("last_status"),
    lastOkAt: text("last_ok_at"),
    lastCheckedAt: text("last_checked_at").notNull(),
    sourceRunId: text("source_run_id"),
  },
  (table) => [
    primaryKey({ columns: [table.ownerId, table.provider, table.modelId] }),
    index("model_availability_owner_available_idx").on(
      table.ownerId,
      table.available,
      table.provider,
    ),
  ],
);
